(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞M"]=[{"q": "In an exact row, what is each map’s reach?", "a": "the next map’s loss", "w": ["the next map’s reach", "empty", "the whole of the next group"], "why": "Exact rows."}, {"q": "0 → A → B → C → 0 is exact, all finite. What is |B|?", "a": "|A| · |C|", "w": ["|A| + |C|", "|C| − |A|", "|A|"], "why": "The short-row technique."}, {"q": "The snake map δ goes from what to what?", "a": "from what γ loses to what α leaves unreached", "w": ["from A to C", "from B back to B", "from what α loses to what γ loses"], "why": "The snake technique, found by chasing members."}, {"q": "What is ℤ/4 ⊗ ℤ/6?", "a": "a clock of 2", "w": ["a clock of 24", "a clock of 12", "0"], "why": "The clock-loss technique: a clock of the greatest common divisor."}, {"q": "How many stacks of ℤ/2 on ℤ/2 are there?", "a": "two: the clock of 4 and ℤ/2 × ℤ/2", "w": ["one", "four", "none"], "why": "The two-stacks technique."}, {"q": "Which of those two stacks does not split?", "a": "the clock of 4", "w": ["ℤ/2 × ℤ/2", "both", "neither"], "why": "The two-stacks technique."}, {"q": "Doubling ℤ, then taking the remainder mod 2. Does that stack split?", "a": "no", "w": ["yes", "only for even numbers", "only in ℤ/4"], "why": "The no-split technique."}, {"q": "The part lost by tensoring. Its accepted name?", "a": "Tor", "w": ["Ext", "the cokernel", "the image"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞ר‎"]=[{"q": "What are the points of a ring here?", "a": "its prime parts", "w": ["its members", "its units", "its zero divisors"], "why": "The points of ℤ."}, {"q": "At which points of ℤ does 12 vanish?", "a": "at (2) and (3)", "w": ["at (12) only", "at every point", "at (0)"], "why": "The vanish technique."}, {"q": "What vanishes at the point (0) of ℤ?", "a": "only 0", "w": ["every number", "every prime", "1"], "why": "The vanish technique."}, {"q": "Why is the union of two closed sets closed?", "a": "V(I) ∪ V(J) = V(IJ)", "w": ["V(I) ∪ V(J) = V(I + J)", "it is always the whole space", "closed sets never meet"], "why": "The closed-union technique."}, {"q": "In the polynomials over ℝ, (x² + 1) is one point. What does it stand for?", "a": "the pair i, −i", "w": ["the number 1", "the number −1", "no number"], "why": "The paired-point technique."}, {"q": "How many points of ℤ[ω] lie over (3)?", "a": "two", "w": ["one", "three", "none"], "why": "The lying-over technique."}, {"q": "The ring maps from A to a ring R match what?", "a": "the solutions of a² + b² = 1 in R", "w": ["the members of R", "the primes of R", "the units of A"], "why": "The points-are-solutions technique."}, {"q": "The space of prime parts of a ring. Its accepted name?", "a": "the spectrum, Spec R", "w": ["the Stone space", "the dual group", "the projective line"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞ד‎"]=[{"q": "A surface with rims goes to what?", "a": "a straight map from its incoming rims’ space to its outgoing rims’", "w": ["a single circle, its outer rim", "a set of points, one per rim", "a group, its loops"], "why": "Surfaces as arrows."}, {"q": "A closed surface has no rims. What does it go to?", "a": "a number", "w": ["a circle", "a space of vectors", "nothing"], "why": "No rims in, none out."}, {"q": "Gluing two surfaces along whole circles. What happens to their counts χ?", "a": "they add", "w": ["they multiply", "the larger wins", "they cancel"], "why": "The glued-count technique."}, {"q": "How many pieces does a sphere with g handles cut into?", "a": "2g + 2", "w": ["g", "4g", "g + 1"], "why": "The four-pieces technique."}, {"q": "Which shapes fix the whole rule, each read both ways?", "a": "a disc and a pair of trousers", "w": ["a sphere and a doughnut", "a circle alone", "a cylinder"], "why": "Four kinds of piece."}, {"q": "With the small choice of space, what does a sphere with g handles go to?", "a": "2ᵍ", "w": ["2g", "g²", "1"], "why": "The genus-count technique."}, {"q": "For every rule of this kind, what does the doughnut go to?", "a": "dim A", "w": ["0", "1", "2"], "why": "The doughnut technique, as ∞א‎’s loop was n."}, {"q": "Such a rule from surfaces to spaces of vectors. Its accepted name?", "a": "a two-dimensional topological quantum field theory", "w": ["a sheaf on the surfaces", "a Frobenius manifold", "a cobordism group of surfaces"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞2"]=[{"q": "How many levels does rung 47’s natural map make?", "a": "three: things, arrows, arrows between arrows", "w": ["two: things and arrows", "one: things", "four"], "why": "Arrows between arrows."}, {"q": "In how many ways do arrows between arrows run in a row?", "a": "two: along and across", "w": ["one", "three", "none"], "why": "Along and across."}, {"q": "(β′ ∘ β) ∗ (α′ ∘ α) equals what?", "a": "(β′ ∗ α′) ∘ (β ∗ α)", "w": ["(β ∗ α′) ∘ (β′ ∗ α)", "β ∘ α", "α ∗ β"], "why": "The interchange technique."}, {"q": "Two ways of combining share a do-nothing and obey interchange. What follows?", "a": "they are the same way, and it turns about", "w": ["they differ", "neither turns about", "only one has a do-nothing"], "why": "The two-become-one technique."}, {"q": "Which loop group of a space always turns about?", "a": "the second", "w": ["the first", "neither", "only the first of a circle"], "why": "The second-loops technique."}, {"q": "Must rung 34’s first loop group turn about?", "a": "no", "w": ["yes", "only for spheres", "only for finite spaces"], "why": "Only from the second level up."}, {"q": "Which of ∞Ε’s rules was the first of the tower’s rules?", "a": "the pentagon", "w": ["the triangle", "the snake", "the square"], "why": "Levels without end."}, {"q": "The two-become-one technique. Its accepted name?", "a": "the Eckmann–Hilton argument", "w": ["the Yoneda lemma", "the snake lemma", "the Whitehead lemma"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞8"]=[{"q": "The run H, a turn by φ, H, from |0⟩. With what chance does it read 1?", "a": "sin²(φ/2)", "w": ["cos²(φ/2)", "φ/2π", "sin φ"], "why": "Roads that cancel: parts add before they are squared."}, {"q": "m qubits together. What is the dimension of their joint space?", "a": "2ᵐ", "w": ["2m", "m²", "m"], "why": "A product of m copies of ℂ²."}, {"q": "H on each of m qubits, from |0⋯0⟩. What comes out?", "a": "the even spread over all 2ᵐ basis states", "w": ["|1⋯1⟩", "|0⋯0⟩ again", "a single random basis state"], "why": "The register-size technique."}, {"q": "A register evenly spread over x₀ + jr, r dividing Q, then the turning transform. Which readings can come out?", "a": "whole multiples of Q/r", "w": ["whole multiples of r", "only 0", "every k equally"], "why": "The turning transform finds a period."}, {"q": "Roughly how many gates does the turning transform take on m qubits?", "a": "about m²/2", "w": ["about 2ᵐ", "about m", "about m!"], "why": "One H and l − 1 turnings on each qubit."}, {"q": "When r does not divide Q, how is c/r read off the reading k?", "a": "as a convergent of the staircase of k/Q, once Q ≥ N²", "w": ["as k divided by r", "by rounding k to a multiple of r", "it cannot be read"], "why": "The nearest-peak technique."}, {"q": "A run factors N with a few repeats. What does each run cost, about?", "a": "n³ gates, mostly computing bˣ", "w": ["2ⁿ gates", "n gates", "one gate per digit of N"], "why": "The whole of it, counted."}, {"q": "The turning transform on qubits. Its accepted name?", "a": "the quantum Fourier transform", "w": ["the Walsh–Hadamard transform", "the Rabi transform", "the phase gate"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞土"]=[{"q": "A qubit driven on its own frequency. What is the chance of 1 after time t?", "a": "sin²(Ωt/2)", "w": ["cos(Ωt)", "Ωt/2", "e^(−Ωt)"], "why": "Driven at its own frequency, it swings."}, {"q": "Driven off frequency by Δ. What ceiling does the chance of 1 never pass?", "a": "Ω²/(Ω² + Δ²)", "w": ["Δ²/(Ω² + Δ²)", "½", "1"], "why": "Off frequency the swing is shallow."}, {"q": "N random turnings of ±ε. How does the average of e^(iθ) fade?", "a": "as (cos ε)ᴺ, about e^(−Nε²/2)", "w": ["as 1/N", "as ε·N", "it does not fade"], "why": "Noise as a small random turning."}, {"q": "Can one gate copy every state of a qubit?", "a": "no: only states equal or at right angles", "w": ["yes, with enough qubits", "yes, if it is slow", "only the state |0⟩"], "why": "No copying."}, {"q": "u|000⟩ + v|111⟩, and two readings: do 1 and 2 agree, do 2 and 3 agree. What do they find?", "a": "which qubit flipped, leaving u and v alone", "w": ["the values of u and v", "whether all three flipped", "nothing about the flip"], "why": "Three qubits against one flip."}, {"q": "d = 2t − 1 qubits, each flipping with chance p. When can the majority’s failure be made as small as wished?", "a": "when p < ¼, by making d larger", "w": ["for any p, with d = 3", "only when p = 0", "when p > ½"], "why": "A threshold."}, {"q": "The grid code below threshold. What does each step from d to d + 2 do to the failure?", "a": "divides it by Λ = p*/p", "w": ["doubles it", "adds p to it", "leaves it alone"], "why": "The grid code."}, {"q": "The swing of a driven qubit. Its accepted name?", "a": "Rabi oscillation", "w": ["Ramsey fringes", "dephasing", "Shor’s swing"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞6"]=[{"q": "A fixed word of k letters in a random string with W starting places. How often is it expected?", "a": "W/4ᵏ times", "w": ["W · 4ᵏ times", "k/W times", "once, always"], "why": "Three billion letters, read both ways."}, {"q": "A 20-letter word in a genome of 3 × 10⁹ letters, both strands. About how often by chance?", "a": "about 0.0055 times", "w": ["about 55 times", "about once", "about 6 × 10⁹ times"], "why": "6 × 10⁹ / 4²⁰."}, {"q": "A full test is made only where a signal appears, with chance q. What happens to the chance matches?", "a": "they are multiplied by q", "w": ["they are divided by q", "they are unchanged", "they vanish"], "why": "A short signal first."}, {"q": "How many words of k letters differ from a given one in exactly j places?", "a": "C(k, j) · 3ʲ", "w": ["kʲ", "4ʲ", "C(k, j)"], "why": "Near matches."}, {"q": "X is a sum of independent 0-or-1 counts with mean μ. A bound on P(X ≥ t) for t > μ?", "a": "e^(−μ)(eμ/t)ᵗ", "w": ["μ/t", "e^(−t)", "t/μ"], "why": "How far the count can stray."}, {"q": "A virus escapes each of m stored stretches with chance q, independently. Chance it escapes all?", "a": "qᵐ", "w": ["mq", "q/m", "1 − qᵐ"], "why": "A memory of past viruses."}, {"q": "The short signal beside the target. Its accepted name?", "a": "the PAM, protospacer adjacent motif", "w": ["the spacer", "the guide RNA", "the repeat"], "why": "The cellar."}, {"q": "The stored stretches in the CRISPR rows. Their accepted name?", "a": "spacers", "w": ["protospacers", "repeats", "guides"], "why": "The cellar."}];
