(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞金"]=[{"q": "Without the triangle rule, a fast method within any fixed r on every list of costs would give?", "a": "a fast round-of-the-dots test, so NP is fast", "w": ["nothing about other problems", "a cheapest spanning tree", "the best tour, exactly"], "why": "Without the triangle rule, no promise."}, {"q": "The best tour costs at least?", "a": "the cheapest spanning tree", "w": ["twice the cheapest tree", "the cheapest matching", "nothing"], "why": "A tree under every tour."}, {"q": "Under the triangle rule, the doubled tree, shortcut, gives a tour at most?", "a": "twice the best", "w": ["the best", "3/2 times the best", "four times the best"], "why": "A tree under every tour."}, {"q": "Under the triangle rule, the cheapest matching of an even number of places costs at most?", "a": "half the best tour", "w": ["the best tour", "the cheapest tree", "twice the best tour"], "why": "A tree and a matching."}, {"q": "The tree plus the matching of its odd places, walked and shortcut, gives a tour at most?", "a": "3/2 times the best", "w": ["twice the best", "4/3 times the best", "the best"], "why": "A tree and a matching."}, {"q": "Prices with y_u + y_v ≤ c(u, v). Every tour costs at least?", "a": "2(y₁ + ⋯ + y_n)", "w": ["y₁ + ⋯ + y_n", "max y", "0"], "why": "Prices on the places."}, {"q": "On some lists, by what factor does the split floor sit under the best?", "a": "near 4/3", "w": ["near 2", "near 3/2", "exactly 1"], "why": "The guess of a third."}, {"q": "The tree-and-matching method. Its accepted name?", "a": "the Christofides algorithm", "w": ["Kruskal’s algorithm", "Dijkstra’s algorithm", "the nearest-neighbour method"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞χ"]=[{"q": "A chain of n joints, each set one of k ways. How many shapes?", "a": "kⁿ", "w": ["nᵏ", "kn", "n!"], "why": "Too many shapes to try."}, {"q": "200 joints of 3 settings give about how many shapes?", "a": "2.7 × 10⁹⁵", "w": ["600", "10²⁰", "3 × 10²⁰⁰"], "why": "Too many shapes to try."}, {"q": "Eight bridge-forming letters can pair in how many ways?", "a": "105", "w": ["8", "28", "40 320"], "why": "The letters decide."}, {"q": "2m things split into m pairs: how many ways?", "a": "(2m − 1)(2m − 3) ⋯ 3 · 1", "w": ["(2m)!", "m!", "2ᵐ"], "why": "The letters decide."}, {"q": "One shape of energy −ε against W shapes of energy 0. Its share?", "a": "1/(1 + We^(−ε/kT))", "w": ["1/W", "e^(−ε/kT)", "ε/kT"], "why": "A landscape with one deep bottom."}, {"q": "So the folded shape wins once?", "a": "ε > kT ln W", "w": ["ε > W", "ε > kT", "W < 1"], "why": "A landscape with one deep bottom."}, {"q": "Two distances, from A and from B, fix a point in the plane how far?", "a": "up to a mirror image across AB", "w": ["exactly", "not at all", "up to a turn"], "why": "A shape as a grid of distances."}, {"q": "The count of too many shapes to try. Its accepted name?", "a": "Levinthal’s paradox", "w": ["Anfinsen’s dogma", "the Ramachandran plot", "the hydrophobic effect"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞Μ"]=[{"q": "A graph without cycles claims what of each variable?", "a": "it depends only on its parents", "w": ["it depends on every other", "it depends on none", "it causes all others"], "why": "A reversal, drawn."}, {"q": "How do the chances of the whole come out?", "a": "as a product over parents", "w": ["as a sum over parents", "as P(x)P(y) only", "as one table"], "why": "A reversal, drawn."}, {"q": "What does doing x do to the graph?", "a": "cuts the arrows into X", "w": ["cuts the arrows out of X", "adds an arrow", "nothing"], "why": "A reversal, drawn."}, {"q": "Z blocks every side path from X to Y. What is P(y | do x)?", "a": "Σ_z P(z)P(y | x, z)", "w": ["P(y | x)", "P(y)", "Σ_z P(y | z)"], "why": "The side-path rule on four dots."}, {"q": "Two graphs share every seen chance. Can they give different effects of doing?", "a": "yes: 0.8 in one and 0.5 in the other", "w": ["no, never", "only if one has a cycle", "only for doing nothing"], "why": "What no data can tell."}, {"q": "Y = βX + U, Z moves X and is untied to U. What is β?", "a": "Cov(Z, Y)/Cov(Z, X)", "w": ["Cov(X, Y)/Var X", "Cov(Z, X)/Cov(Z, Y)", "Var Y/Var X"], "why": "A lever from outside."}, {"q": "A dot where two arrows collide. Its accepted name?", "a": "a collider", "w": ["a confounder", "a mediator", "an instrument"], "why": "The cellar."}, {"q": "Averaging over Z when it blocks every side path. Its accepted name?", "a": "the back-door adjustment", "w": ["the front-door adjustment", "regression to the mean", "collider bias"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞b"]=[{"q": "m false ideas, each tested at α. How many pass on average?", "a": "mα", "w": ["α", "m", "α/m"], "why": "Fifty false passes."}, {"q": "Each idea tested at α/m. The chance any false idea passes is at most?", "a": "α, however the tests depend", "w": ["α/m", "mα", "1"], "why": "Fifty false passes."}, {"q": "The step rule passes the first k sorted ideas, for the largest k with?", "a": "p₍ₖ₎ ≤ qk/m", "w": ["p₍ₖ₎ ≤ q", "p₍ₖ₎ ≤ q/m", "p₍ₖ₎ ≥ qk/m"], "why": "A share, not a chance."}, {"q": "For independent tests, the step rule keeps the average false share at?", "a": "m₀q/m, at most q", "w": ["q/m", "q", "m₀q"], "why": "Why the share is controlled."}, {"q": "What does the step rule control, against the split level?", "a": "a share of the passes, not the chance of any false pass", "w": ["the chance of any false pass", "the number of true ideas", "nothing"], "why": "A share, not a chance."}, {"q": "A new error ranked among n past errors. Its rank is?", "a": "any of n + 1 ranks with equal chance", "w": ["always last", "always first", "the middle"], "why": "A width from ranks."}, {"q": "A width set at the ⌈(n + 1)(1 − α)⌉-th smallest past error covers the new value with chance?", "a": "at least 1 − α", "w": ["exactly α", "at most 1 − α", "½"], "why": "A width from ranks."}, {"q": "The step rule. Its accepted name?", "a": "the Benjamini–Hochberg procedure", "w": ["the Bonferroni correction", "Holm’s method", "the Bayes factor"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞三"]=[{"q": "A sort asks k yes-or-no questions. Why must n! be at most 2ᵏ?", "a": "orders go one-to-one into rows of answers", "w": ["each question halves the list", "every item is compared k times", "the rows outnumber the items"], "why": "The orders-into-rows technique."}, {"q": "What is the least number of comparisons that always sorts five items?", "a": "7", "w": ["6", "8", "10"], "why": "The five-in-seven technique: ⌈log₂ 120⌉ = 7."}, {"q": "With j questions left, how many orders may still be possible?", "a": "at most 2ʲ", "w": ["at most j", "at most j!", "exactly n! − j"], "why": "The tight-split technique."}, {"q": "For twelve items the floor says 29. What is the true least number?", "a": "30", "w": ["29", "31", "33"], "why": "Found by a machine search in the 1960s."}, {"q": "From which n on is the least number of comparisons not known?", "a": "23", "w": ["13", "17", "47"], "why": "S(23) is 75 or 76."}, {"q": "A sort learns by looks with b outcomes each. What takes the place of n! ≤ 2ᵏ?", "a": "n! ≤ bᵏ", "w": ["n! ≤ kᵇ", "n ≤ bk", "n! ≤ 2ᵇ"], "why": "The many-outcomes technique."}, {"q": "Counting sort beats n log n. Why is the floor still true?", "a": "the floor is about comparing only", "w": ["counting sort makes mistakes", "the floor holds only for small n", "it compares in secret"], "why": "Outside the plan."}, {"q": "Questions and answers drawn as a branching figure. Its accepted name?", "a": "a decision tree", "w": ["a search heap", "a sorting network", "a trie"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞q"]=[{"q": "A sketch keeps the least stamp seen. What does a repeat visit do to it?", "a": "nothing", "w": ["lowers it", "raises it", "resets it to 1"], "why": "The repeat-blind technique."}, {"q": "n different names get stamps drawn evenly from [0, 1). Where does the least stamp sit on average?", "a": "at 1/(n + 1)", "w": ["at 1/n²", "at 1/2", "at 1/√n"], "why": "The smallest-draw technique."}, {"q": "One least stamp alone gives a poor count. Why?", "a": "its width is about its own size", "w": ["it is always too small", "it forgets the first name", "it depends on the order of arrival"], "why": "The spread of the least draw."}, {"q": "k least stamps are averaged. How does the width of the average shrink?", "a": "like 1/√k", "w": ["like 1/k", "like 1/k²", "not at all"], "why": "The averaged-stamps technique."}, {"q": "Two servers keep sketches of sets A and B. What is the sketch of A ∪ B?", "a": "the place-by-place min of the two", "w": ["the sum of the two", "the place-by-place max of the two", "it cannot be had"], "why": "The sketch-merge technique."}, {"q": "Can the sketch of A ∩ B be had from the sketches of A and B?", "a": "no function gives it", "w": ["yes, by the max", "yes, by the min", "yes, by subtracting"], "why": "The no-meet technique."}, {"q": "To halve the error of the count, how much more room is needed?", "a": "four times", "w": ["twice", "eight times", "one more register"], "why": "1/√k again."}, {"q": "The 2007 sketch of five-bit registers. Its accepted name?", "a": "HyperLogLog", "w": ["a Bloom filter", "MinHash", "Count-Min"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞I"]=[{"q": "Rent is $1 a day and the price is $B. What does a buyer who knows the season pay?", "a": "the smaller of D and B", "w": ["always B", "always D", "D + B"], "why": "Hindsight."}, {"q": "The rule rents B − 1 days and then buys. What is the most it pays, against hindsight?", "a": "2 − 1/B times as much", "w": ["exactly as much", "B times as much", "3 times as much"], "why": "The rent-to-the-price technique."}, {"q": "Against a rule that buys on day k, which season does the opponent pick?", "a": "the one that ends on day k", "w": ["the shortest", "the longest", "one of B days"], "why": "The worst-season technique."}, {"q": "A rule never buys. What ratio to hindsight can it promise?", "a": "none", "w": ["2", "B", "1"], "why": "D/B passes every number."}, {"q": "B = 2. With what chance should the rule buy on day 1 to promise 4/3?", "a": "1/3", "w": ["1/2", "2/3", "1/4"], "why": "The one-coin technique."}, {"q": "For large B, the best ratio a rule with a coin can promise heads to what?", "a": "e/(e − 1), about 1.58", "w": ["2", "1", "√2, about 1.41"], "why": "From 1990."}, {"q": "Trust λ in a forecast. The forecast is on the wrong side of B. What bounds the ratio?", "a": "1 + 1/λ", "w": ["1 + λ", "2", "λ"], "why": "The trusted-forecast technique."}, {"q": "The worst ratio of a rule’s cost to hindsight. Its accepted name?", "a": "the competitive ratio", "w": ["the regret", "the approximation ratio", "the price of anarchy"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞w"]=[{"q": "How many products of numbers does the school rule use for two n by n grids?", "a": "n³", "w": ["n²", "2n²", "n⁴"], "why": "One for each i, j, k."}, {"q": "Two by two grids can be multiplied with how many products?", "a": "7", "w": ["8", "6", "4"], "why": "The seven-products technique."}, {"q": "Why may the entries of the seven-product rule be grids themselves?", "a": "it never swaps the factors of a product", "w": ["grids swap like numbers", "it uses no additions", "it divides nowhere"], "why": "The a’s stay on the left."}, {"q": "An r-product rule for m by m grids gives which exponent?", "a": "log_m r", "w": ["r/m", "log_r m", "m·r"], "why": "The stacking technique."}, {"q": "Why must every rule for n by n grids use at least n² products?", "a": "its fixed grids must build every grid", "w": ["each entry needs two products", "additions are not allowed", "the school rule uses n²"], "why": "The square-floor technique: set B = I."}, {"q": "With three slots, what can a limit of two-term members need?", "a": "three terms", "w": ["one term", "at most two", "none"], "why": "The limit-of-two technique."}, {"q": "What is the best bound proved on ω by August 2026?", "a": "2.371177", "w": ["2.807", "2.5", "2"], "why": "From 2.371339 in 2024."}, {"q": "The fewest terms that serve in the limit. Its accepted name?", "a": "the border rank", "w": ["the tensor rank", "the nullity", "the condition number"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞9"]=[{"q": "When does the slope pay at rate μ?", "a": "when ½|∇f|² ≥ μ·f", "w": ["when f ≤ μ", "when |∇f| ≤ μ", "when f bends up"], "why": "Steep where high."}, {"q": "The slope pays at rate μ along a walk with steps 1/L. What does each step do to f?", "a": "multiplies it by at most 1 − μ/L", "w": ["lowers it by μ", "halves it", "multiplies it by μ/L"], "why": "The slope-pays technique."}, {"q": "f = ½(uv − 1)². What kind of point is (0, 0)?", "a": "a saddle", "w": ["a bottom", "a top", "not a flat point"], "why": "The two-knob technique."}, {"q": "For f = ½(uv − 1)², what is ½|∇f|²?", "a": "(u² + v²)·f", "w": ["u·v·f", "(u − v)²·f", "f²"], "why": "The two-knob technique."}, {"q": "f = ½|F(w) − y|², with J the slope grid of F. What is ∇f?", "a": "Jᵀ(F(w) − y)", "w": ["J(F(w) − y)", "JJᵀ", "F(w) − y"], "why": "The wide-grid technique."}, {"q": "Every stretch of JJᵀ can be above 0 only when what holds?", "a": "at least as many knobs as answers", "w": ["more answers than knobs", "J is square", "the error is a bowl"], "why": "n columns must build lists of m."}, {"q": "In 2021 networks were seen to train with the sharpest bend sitting near what?", "a": "2/η", "w": ["0", "η", "1/η²"], "why": "Seen, not proved."}, {"q": "The inequality ½|∇f|² ≥ μ·f. Its accepted name?", "a": "the Polyak–Łojasiewicz inequality", "w": ["the Cauchy–Schwarz inequality", "Jensen’s inequality", "the triangle inequality"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞D"]=[{"q": "A rule’s miss rate is ε. With what chance is it right on m fresh examples?", "a": "(1 − ε)ᵐ", "w": ["1 − mε", "εᵐ", "1 − εᵐ"], "why": "Independent chances multiply."}, {"q": "A family of N rules. About how many examples make a lucky fit unlikely?", "a": "(ln N + ln(1/δ))/ε", "w": ["N/ε", "N·ln(1/δ)", "ε·ln N"], "why": "The lucky-fit technique."}, {"q": "Rules are named by k bits. How do the examples needed grow?", "a": "in proportion to k", "w": ["like 2ᵏ", "like k²", "not at all"], "why": "ln N ≤ k·ln 2."}, {"q": "Thresholds on a line are endlessly many. How many rows of answers do they give on m points?", "a": "m + 1", "w": ["2ᵐ", "m²", "endlessly many"], "why": "Count rows, not rules."}, {"q": "How many points can thresholds answer in every way?", "a": "one", "w": ["two", "three", "none"], "why": "Yes to x and no to a larger x′ never happens."}, {"q": "More knobs than examples, and the walk starts at 0. Which fit does it reach?", "a": "the fit of least size", "w": ["the fit with most zeros", "the fit nearest y", "a random fit"], "why": "The least-size technique."}, {"q": "In 2017, what did working networks do with answers drawn at random?", "a": "fitted them exactly", "w": ["refused to train", "fitted half of them", "did as well on fresh examples"], "why": "So a count of rows explains nothing."}, {"q": "The largest number of points a family answers in every way. Its accepted name?", "a": "the VC dimension", "w": ["the rank", "the margin", "the covering number"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞十"]=[{"q": "In an attention step, what do the weights in one row add to?", "a": "1", "w": ["0", "T", "the number of knobs"], "why": "The row-average technique."}, {"q": "The tokens of a passage are shuffled. What happens to the outputs?", "a": "the same rows, shuffled the same way", "w": ["all rows change", "nothing moves", "the first row only changes"], "why": "The order-blind technique."}, {"q": "So how does a text machine know the order of its tokens?", "a": "each token is marked with its place", "w": ["the step works left to right", "the weights remember it", "the scores are sorted"], "why": "Marks are added before the step."}, {"q": "The scores are S = (XA)(XB)ᵀ. Through what alone do A and B count?", "a": "the product ABᵀ", "w": ["the sum A + B", "A alone", "the larger of the two"], "why": "The score-form technique."}, {"q": "A and B have k columns each. What is the rank of ABᵀ at most?", "a": "k", "w": ["d", "2k", "k²"], "why": "k terms a·bᵀ."}, {"q": "A passage twice as long costs how much more work?", "a": "four times", "w": ["twice", "eight times", "the same"], "why": "T by T grids."}, {"q": "With no soft weighing, one attention step can carry out what on the examples in its passage?", "a": "one step of the walk downhill", "w": ["a full sort", "a grid inverse", "a count of distinct tokens"], "why": "The one-step technique."}, {"q": "The soft weighing of a row of scores. Its accepted name?", "a": "the softmax", "w": ["the sigmoid", "the argmax", "the hinge"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞P"]=[{"q": "Every group’s count is answered within E. How close to the true list can a searcher get?", "a": "within 4E rows", "w": ["within E² rows", "no closer than half", "within n/E rows"], "why": "The list-rebuild technique."}, {"q": "Heads: tell the truth. Tails: toss again and report that coin. Chance of “yes” when the truth is yes?", "a": "3/4", "w": ["1/2", "1/4", "1"], "why": "The coin-answer technique."}, {"q": "q̂ is the share of yes reports under the coin answers. What is the guess at the true share?", "a": "2q̂ − ½", "w": ["q̂", "q̂/2", "4q̂"], "why": "q = ¼ + p/2, turned round."}, {"q": "A release is ε-private. One row of the list changes. By what factor at most can a report’s chance change?", "a": "e^ε", "w": ["ε", "1 + 1/ε", "2"], "why": "The promise."}, {"q": "A count plus noise of density (ε/2)e^(−ε|z|). How does the error grow with the list?", "a": "it does not", "w": ["like √n", "like n", "like ln n"], "why": "The noised-count technique: width √2/ε."}, {"q": "A map is applied to the report of an ε-private release. How private is the result?", "a": "ε-private still", "w": ["2ε-private", "not private", "ε/2-private"], "why": "The afterwards technique."}, {"q": "Two releases, ε₁ and ε₂, with noise drawn apart. Together they are what?", "a": "(ε₁ + ε₂)-private", "w": ["ε₁·ε₂-private", "as private as the worse one", "as private as the better one"], "why": "The losses-add technique."}, {"q": "The promise that a report is nearly as likely with any one row changed. Its accepted name?", "a": "differential privacy", "w": ["k-anonymity", "encryption", "secret sharing"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞·phys"]=[{"q": "A crowbar multiplies force by 12 and drives a pulley block that multiplies by 4. What does the train multiply force by?", "a": "48", "w": ["16", "8", "3"], "why": "A row composes, and composing multiplies."}, {"q": "A train of ideal machines multiplies force by 48. By what does it multiply the distance moved?", "a": "1/48", "w": ["48", "1", "1/16"], "why": "Train-ratio: the two products multiply to 1."}, {"q": "Unit vectors a and b at right angles. How many vectors of the plane have the parts (u, v) on them?", "a": "exactly one, ua + vb", "w": ["none unless a points east", "two, one on each side", "one for each angle"], "why": "Parts-fix: the plane is a product of two number lines."}, {"q": "Two forces are added on east and north axes, then again on axes turned by 30°. What agrees?", "a": "the sum, and so its size", "w": ["the parts of the sum", "the first part only", "nothing, as a rule"], "why": "The sum is one vector; each pair of axes only reads it."}, {"q": "Three changes of observer in a row, each a turn by ln 2. Which one change is that?", "a": "the turn by ln 8", "w": ["the turn by 3 ln 8", "the turn by (ln 2)³", "no one change"], "why": "Observer-row: the turns add."}, {"q": "A filter is P = i ∘ r with r ∘ i do-nothing. Between two filters, what is the light?", "a": "one number", "w": ["a vector of the plane", "a pair of numbers", "a shadow map"], "why": "Through-the-line: r reads a number, and i sends it out."}, {"q": "Filters at 0° then 45° give P₂ ∘ P₁. Along which line does the light leave?", "a": "along 45°, the last i", "w": ["along 0°, the first r", "along 22.5°", "along either, alike"], "why": "The row ends with the last filter’s i."}, {"q": "A gate U acts on the first qubit of the pair Φ. Which gate on the second qubit makes the same state?", "a": "Uᵀ", "w": ["U", "U⁻¹", "no gate does"], "why": "Cup-state: the box slides round the cup and comes out turned over."}, {"q": "One tick T keeps an amount: Q ∘ T = Q. What do 1000 ticks do to Q?", "a": "keep it exactly", "w": ["keep it to within 1000 small errors", "keep it only for short ticks", "nothing can be said"], "why": "Kept-along, by induction on the count of ticks."}, {"q": "Its accepted name: an arrow P with P ∘ P = P, written as i ∘ r with r ∘ i do-nothing.", "a": "a split idempotent", "w": ["a natural transformation", "a Lorentz boost", "a symplectic map"], "why": "r is the retraction and i the section; a filter’s shadow map is one."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞·bio"]=[{"q": "Two whole branches share one member. What follows?", "a": "one lies inside the other", "w": ["they are the same branch", "they share an ancestor only", "nothing follows"], "why": "Nested-or-apart: the two ancestors lie in a line."}, {"q": "A kind shares a member with the mammals, and neither holds the other. What is shown?", "a": "the kind is no whole branch", "w": ["the mammals are no whole branch", "the kind is a whole branch", "the shared member is the ancestor"], "why": "Whole branches that share a member are nested."}, {"q": "Where does nested-or-apart fail?", "a": "where two lines of descent join", "w": ["where a branch has one member", "where an ancestor has died out", "where traits are shared"], "why": "Its given is that the ancestors of a thing lie in a line."}, {"q": "Three genes are handed on separately. How many of 64 cells show all three dominant looks?", "a": "27", "w": ["9", "48", "3"], "why": "Looks-multiply: 3 · 3 · 3."}, {"q": "Before the counts of two grids are multiplied, what must be asked?", "a": "is the big grid their product, with equal chances", "w": ["are both genes dominant", "are the parents alike", "is each grid drawn"], "why": "Genes handed on together break the product."}, {"q": "A ring of five parts, each the opposite of the one before. How many on-or-off states hold?", "a": "none", "w": ["one", "two", "five"], "why": "Ring-rest: once round is one opposite, and it keeps nothing fixed."}, {"q": "A ring of six parts, each the opposite of the one before. What is it?", "a": "a switch with two held states", "w": ["a clock", "a ring with no state", "a clock of period six"], "why": "Six opposites in a row are do-nothing."}, {"q": "What does the on-or-off reading of a ring leave out?", "a": "the middle state, and how steep the switches are", "w": ["the number of parts", "the order of the parts", "which part is first"], "why": "An odd ring ticks only if its switches are steep."}, {"q": "In a tree, d(p, q) = 10, d(p, r) = 14, d(q, r) = 12. How far is p from the dot where the three paths meet?", "a": "6", "w": ["4", "8", "12"], "why": "Three-ends: ½(10 + 14 − 12)."}, {"q": "Why is the tree for twenty kinds never found by listing trees?", "a": "there are about 2.2 × 10²⁰ of them", "w": ["no table fits a tree", "the fours cannot be tested", "twenty kinds have no tree"], "why": "It is built by threes and tested by fours. Its accepted name is the quartet method."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞·crypt"]=[{"q": "A family of keys is closed under composing. What does a second lock add?", "a": "nothing: two keys are one key", "w": ["twice the keys to try", "the square of the keys to try", "a way to undo the first"], "why": "Closed-keys."}, {"q": "Shift by 3, then 5, then 11. Which one shift is that?", "a": "shift by 19", "w": ["shift by 165", "shift by 9", "no one shift"], "why": "Keys add on the clock of 26."}, {"q": "Encrypt with a scrambled alphabet g, then tally. The table is the message’s table, changed how?", "a": "its labels moved by g", "w": ["its values put in order", "every value doubled", "not at all"], "why": "The square: tally(g · m) = tally(m) ∘ g⁻¹."}, {"q": "Which of these can an enemy read off a scrambled-alphabet secret text with no key?", "a": "the tallies put in order", "w": ["the commonest plain letter", "the first letter of the message", "the key’s first pair"], "why": "Kept by every key."}, {"q": "X ↦ S⁻¹XS, applied to a product XY. What comes out?", "a": "the product of the two sandwiches", "w": ["the sandwiches in the other order", "S⁻¹XS · Y", "XY unchanged"], "why": "The inner S S⁻¹ is do-nothing."}, {"q": "R sends no letter to itself. How many letters does S⁻¹RS send to themselves?", "a": "none, for every S", "w": ["it depends on S", "one", "all 26"], "why": "The sandwich matches kept letters with kept letters."}, {"q": "A uniform pad of n bits. P(secret text c, given message m)?", "a": "2⁻ⁿ, for every m and c", "w": ["1 for one c, else 0", "the chance of m", "it depends on m"], "why": "Exactly one key sends m to c."}, {"q": "Message and secret text under a fresh uniform pad. What does their joint picture do?", "a": "falls into two pieces", "w": ["joins by one wire", "copies the message", "repeats the key"], "why": "Independent: the marginals side by side."}, {"q": "Curves of degree at most 2 on a prime clock, valued at any three different hours. What are they?", "a": "a product of three copies of the clock", "w": ["a sum of three clocks", "a single clock", "a clock of p² hours"], "why": "One curve for each triple of values."}, {"q": "Its accepted name, for a picture of message and secret text that falls in two?", "a": "perfect secrecy", "w": ["public-key secrecy", "a hash", "a checksum"], "why": "The one-time pad has it."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞·comp"]=[{"q": "A check q can be read only where p passed. Which row exists?", "a": "q ⋆ p only", "w": ["p ⋆ q only", "both, and they are equal", "neither"], "why": "Guard-row: the ends must meet."}, {"q": "F ∧ L and L ∧ F have one column. What is that a fact about?", "a": "the things: the parts of U where both hold", "w": ["the rows of checks", "the order of reading", "the machine’s sensors"], "why": "⋆ has no turn-about."}, {"q": "In the maybe wrapper, when does q ⋆ p run q?", "a": "only where p passed", "w": ["always", "only where p failed", "before p"], "why": "The row stops at the first failure."}, {"q": "A checker of stopping would give which function a fixed point?", "a": "“opposite” on {stops, runs on}", "w": ["the do-nothing function", "the checker itself", "every function on programs"], "why": "Fixed-point technique, ∞Ψ."}, {"q": "In the category of circuits, when are two circuits the same arrow?", "a": "when they have the same table", "w": ["when they use the same gates", "when they have the same number of gates", "when they are drawn alike"], "why": "An arrow there is its table."}, {"q": "Rₙ adds two n-bit numbers and a carry. From how many wires to how many?", "a": "2n + 1 to n + 1", "w": ["2n to n", "n + 1 to n", "3n to 2n"], "why": "Rₙ = (FA ⊕ 1)(1 ⊕ Rₙ₋₁)."}, {"q": "What is the leftover of L after u?", "a": "the strings w with uw in L", "w": ["the strings of L longer than u", "the states reached by u", "the strings of L that start with u"], "why": "What may still follow."}, {"q": "A language has endlessly many leftovers. How many states does a machine with no memory need for it?", "a": "no such machine checks it", "w": ["one for each letter", "as many as its longest string", "two"], "why": "Leftover-count: states ≥ leftovers."}, {"q": "Insertion sort and merge sort are two bracketings. What do they share?", "a": "the sorted list they give", "w": ["the count of comparisons", "the order of comparisons", "the tree"], "why": "One-sort: s is fixed by two demands."}, {"q": "A search of a billion rows of twists finds none that twists one corner alone. What settles it?", "a": "a total that every twist keeps", "w": ["a search of a billion more", "a faster machine", "a shorter row"], "why": "Kept-value: different values, different pieces, for rows of any length."}, {"q": "Its accepted name, for states ≥ leftovers?", "a": "the Myhill–Nerode theorem", "w": ["the pigeonhole principle", "the halting problem", "the pumping lemma"], "why": "With the minimal automaton."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞·chem"]=[{"q": "A weight on bags of molecules can be worked out from the atom count alone. What does every reaction do to it?", "a": "keeps it", "w": ["raises it", "lowers it", "it depends on the reaction"], "why": "Atoms-carry: what passes through the atoms is kept."}, {"q": "2 H₂ + O₂ → 2 H₂O. Which of these is not kept?", "a": "the count of molecules", "w": ["the mass", "the count of hydrogen atoms", "the count of oxygen atoms"], "why": "3 molecules in, 2 out: that count does not pass through the atoms."}, {"q": "A reaction has 6 species and its atom grid reaches a space of dimension 5. How many free balances?", "a": "1", "w": ["5", "6", "11"], "why": "Balance-count: n − r."}, {"q": "The count of free balances comes out 0. What does that say?", "a": "a species is missing", "w": ["the reaction is balanced", "any amounts will do", "the fire sets the mix"], "why": "Only the zero list balances it."}, {"q": "A molecule has 12 moves, and a placement is kept by 3 of them. How many placements are in its piece?", "a": "4", "w": ["3", "9", "36"], "why": "Arrows-by-ends: 12 = 4 · 3."}, {"q": "Two placements are in one piece. What do they share?", "a": "the number of their keepers", "w": ["their keepers themselves", "no keepers at all", "the place of every atom"], "why": "K at gx is gKg⁻¹."}, {"q": "Every arrow keeps q, and q(x) ≠ q(y). How many rows of arrows lead from x to y?", "a": "none", "w": ["one", "one for each value of q", "it cannot be said"], "why": "Kept-apart."}, {"q": "A carbon with four different neighbours, and its mirror image. For which arrows are they one piece?", "a": "turns and mirrors together", "w": ["turns alone", "slides alone", "no arrows at all"], "why": "The mirror is then an arrow from one to the other."}, {"q": "Two bags have the same mass. Must some row of reactions lead from one to the other?", "a": "no: a kept amount only rules out", "w": ["yes, always", "yes, if both are gases", "no: mass is not kept"], "why": "Equal q does not give an arrow."}, {"q": "A machine lists the kinds of carbon tree on ten named dots. Which check can a climber ask of its list?", "a": "each kind’s 10!/k must total the drawings", "w": ["the kinds must number 10!", "each kind must have 10! keepers", "the list must hold 75 drawings"], "why": "Kinds-as-pieces: every drawing lies in exactly one piece."}, {"q": "Its accepted name: the count |G| = (things in the piece) · |K|.", "a": "the orbit-stabilizer theorem", "w": ["the rank-nullity count", "the conservation of mass", "an exact sequence"], "why": "The piece is the orbit and the keepers are the stabilizer."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞·logi"]=[{"q": "Every plan earns at most every bound, and one plan earns exactly one bound. What follows?", "a": "that plan is best and that bound is least", "w": ["that plan is best, the bound may not be least", "nothing, until the corners are walked", "every plan meets every bound"], "why": "Met-bound: each is a proof of the other."}, {"q": "A bound on earnings is 800 and the best plan found earns 700. What is known?", "a": "the best is from 700 to 800", "w": ["the best is 800", "the best is 700", "the bound is wrong"], "why": "A bound that is not met says only “at most”."}, {"q": "What do the bakery’s worths give besides the worth of each limit?", "a": "a proof that its corner is best", "w": ["the number of corners", "the order to walk the corners", "the plan in whole loaves"], "why": "3x + 2y = (2x + y) + (x + y) ≤ 700, met at (100, 200)."}, {"q": "Why are the hands not in the bakery’s one-line proof?", "a": "they have room to spare, so worth 0", "w": ["they are not a limit", "they are the tightest limit", "their worth is unknown"], "why": "A limit the best corner does not touch is worth 0 at the margin."}, {"q": "A machine returns a shipping plan for 600 routes. What should come with it?", "a": "prices that cover every route and meet its cost", "w": ["the list of corners it walked", "a second plan to compare", "the time it took"], "why": "The plan is one side; the prices are the other."}, {"q": "What is the other side of a largest flow?", "a": "a smallest cut", "w": ["a shortest route", "a cheapest plan", "a longest chain"], "why": "Flow is at most cut, and they meet."}, {"q": "Six jobs; a group of four has two drivers between them. How many jobs can be served fairly, at most?", "a": "4", "w": ["2", "5", "6"], "why": "Short-by: 6 − (4 − 2)."}, {"q": "A fair assignment serves 7 of 9 jobs, and a group is short by 2. What is settled?", "a": "7 is the most that can be served", "w": ["8 may still be served", "the group is the only short one", "nothing: the search must go on"], "why": "9 − 2 = 7: the bound is met."}, {"q": "Picking in turn strands a job. Does that show a group short of drivers?", "a": "no: the order of picking is not a bound", "w": ["yes, always", "yes, if two jobs share a driver", "no: no group is ever short"], "why": "A swap may serve every job (6·logi4)."}, {"q": "In whole loaves the best plan earns 9, and the least bound from worths is 29/3. What is the gap called here?", "a": "a bound not met", "w": ["a mistake in the worths", "a corner not walked", "a group short by one"], "why": "With fractions allowed they meet. Its accepted name is the integrality gap."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞·eng"]=[{"q": "Gears of 10 and 15 teeth turn together. Into how many loops do the pairs of teeth fall?", "a": "5 loops of 30 pairs", "w": ["1 loop of 150 pairs", "30 loops of 5 pairs", "150 loops of 1 pair"], "why": "Tooth-loop: lcm(10, 15) = 30, and 150/30 = 5."}, {"q": "When does every tooth of one gear meet every tooth of the other?", "a": "when the pairs make one loop", "w": ["when the counts are equal", "when one count divides the other", "when both counts are even"], "why": "One loop means lcm(g, h) = gh."}, {"q": "A frame has 7 bars and 5 joints. What does the frame-count technique give?", "a": "s − m = 0", "w": ["s = 0 and m = 0", "s − m = 2", "m = 3"], "why": "b − (2j − 3) = 7 − 7. The count gives the difference only."}, {"q": "Why is every load that a frame’s bars produce in balance as a whole?", "a": "each bar pulls its two ends equally and oppositely", "w": ["the joints are pinned", "the bars keep their lengths", "the frame has 2j − 3 bars"], "why": "So what A reaches lies inside the balanced loads."}, {"q": "A square of four bars gets both diagonals. What changes?", "a": "m falls to 0 and s rises to 1", "w": ["s and m both become 0", "m rises to 2", "nothing: b is still below 2j"], "why": "s − m goes from −1 to 1; one diagonal alone gives 0 and 0."}, {"q": "A heater’s push is worked out from the gap alone, with no push at no gap. Where can it rest on a cold night?", "a": "only short of the set point", "w": ["on the set point, if strong enough", "on the set point, after long enough", "above the set point"], "why": "No-memory: at no gap there is no push, and the house still leaks."}, {"q": "What does the heater that adds up the gap have that the proportional one lacks?", "a": "a state of two numbers, (T, I)", "w": ["a larger G", "a faster furnace", "a narrower band"], "why": "Its push does not pass through the gap alone."}, {"q": "Two compilers give runs that end the same on every program tried. What is shown?", "a": "nothing about either being right", "w": ["both are right", "at least one is right", "the programs tried are right"], "why": "The agreement does not hold what the source does."}, {"q": "Three passes each keep the runs. What does the row of the three keep?", "a": "the runs, from source to machine", "w": ["the runs, if tested end to end", "the form of the program", "nothing certain"], "why": "Pass-row: brackets move, and the demands follow one another."}, {"q": "Why must the links between switches be cut to a tree?", "a": "so each address has one port", "w": ["so messages travel faster", "so every port is in use", "so the hub’s rule is never used"], "why": "One-port: one path, one last link. Its accepted name is a spanning tree."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞·nav"]=[{"q": "A voyage is starboard 30, ahead 5, starboard 60, ahead 2. What is its facing?", "a": "90° to starboard of the start", "w": ["it depends on the runs", "30° to starboard of the start", "7 miles ahead"], "why": "Facing-arrow: the turns alone give it."}, {"q": "A ship’s log has lost its turns and kept its runs. What can still be worked out?", "a": "neither the facing nor the place", "w": ["the place, by adding the runs", "the facing only", "the distance from the start"], "why": "Each run is turned by the facing at that moment."}, {"q": "The turns of a voyage add to one full turn. What kind of move is the voyage?", "a": "a slide", "w": ["a turn about a point", "doing nothing", "a turn and a slide"], "why": "The turn part is do-nothing, and a pose is a turn then a slide."}, {"q": "Two poses have the same place. After the same order, must their places agree?", "a": "no: the facing turns the run", "w": ["yes, always", "yes, if the order is a run", "no: the order changes the start"], "why": "The place of a row is not worked out from places alone."}, {"q": "A map stretches by 3 across and by ⅓ up, everywhere. What does it keep?", "a": "sizes", "w": ["shapes", "headings", "distances"], "why": "Areas go by 3 · ⅓ = 1."}, {"q": "The size map is to be true in shape along 60° N. Which squeeze across?", "a": "c = ½", "w": ["c = 2", "c = 0.87", "c = 1"], "why": "Map-row: c = cos 60°."}, {"q": "What does the map-row technique use of each map?", "a": "its two stretches at each latitude", "w": ["its formula", "its height at the pole", "its width at the equator"], "why": "Stretches multiply along a row."}, {"q": "d(P, X) + d(X, Q) is 40 km more than d(P, Q). What follows?", "a": "X is on no shortest route from P to Q", "w": ["X is on the shortest route", "the distances were measured wrongly", "the route through X is shortest"], "why": "Parts-shortest: on a shortest route the detour costs nothing."}, {"q": "A place X lies on a shortest route from P to Q. What is true of the part from P to X?", "a": "it is a shortest route from P to X", "w": ["it is half the route", "it is a line of latitude", "it may be bettered"], "why": "Both “at least” in the proof are “is”."}, {"q": "When is the route by way of the pole a shortest route between two cities?", "a": "when the pole is on their shortest route", "w": ["when both are north of 45°", "when each half is shortest", "never"], "why": "So when the longitudes are equal or 180° apart. Its accepted name is a geodesic."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞·econ"]=[{"q": "Your best reply to her choice b is B(b), hers to your choice a is C(a). When is the pair (a, b) stuck?", "a": "when a = B(b) and b = C(a)", "w": ["when a = C(b) and b = B(a)", "when B(b) = C(a)", "when both do best"], "why": "Each choice is the best reply to the other."}, {"q": "One player’s best reply is the same whatever the other does. How many stuck pairs can the game have?", "a": "exactly one", "w": ["none", "two", "as many as there are choices"], "why": "The reply loop keeps one choice only."}, {"q": "One player wants to match and the other to differ. What does the reply loop keep?", "a": "nothing", "w": ["every choice", "the first choice", "the better choice"], "why": "B(C(a)) is never a: no stuck pair."}, {"q": "A dollar buys 2 marks, and a mark buys 3 crowns. With every loop at 1, how many dollars does a crown buy?", "a": "1/6", "w": ["6", "1/5", "2/3"], "why": "The loop dollar, mark, crown, dollar composes to 1."}, {"q": "Rates have every loop at 1. Two chains lead from one money to another. How do their amounts compare?", "a": "they are equal", "w": ["the shorter chain gives more", "the longer chain gives more", "it depends on the middle moneys"], "why": "One chain, then the other backwards, is a loop."}, {"q": "A market moves its price by T(p) = p − λE(p). λ is doubled. What happens to the prices T keeps?", "a": "they stay the same", "w": ["they double", "they halve", "there are twice as many"], "why": "Kept exactly when E(p) = 0."}, {"q": "A straight surplus with λs = 3. The gap from the matching price, step by step,", "a": "doubles and changes sign", "w": ["halves and keeps its sign", "stays the same", "shrinks to nothing"], "why": "The factor is 1 − 3 = −2."}, {"q": "Among pairings that hold, every doctor likes M at least as well as M′. What of the hospitals?", "a": "each likes M′ at least as well as M", "w": ["each likes M at least as well as M′", "some like M, some M′", "nothing follows"], "why": "Turned-order."}, {"q": "The hospitals propose in place of the doctors. Where in the doctors’ order does the result sit?", "a": "at the bottom", "w": ["at the top", "in the middle", "it varies with the day"], "why": "The hospitals’ top is the doctors’ bottom."}, {"q": "Its accepted name: a loop of exchange rates that composes to more than 1.", "a": "an arbitrage", "w": ["a cobweb", "a fixed point", "a stable matching"], "why": "Loops at 1 are no arbitrage."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞·stat"]=[{"q": "Answers a(x) are in hand, and a question b is wanted. When can b be worked out from a?", "a": "when equal a force equal b", "w": ["when a has more values than b", "when b is one-to-one", "always, with enough members"], "why": "The passes-through technique."}, {"q": "One member answers (yes, no) and another (yes, yes). Which question tells them apart?", "a": "the both-question", "w": ["the or-question", "the either-question", "no question can"], "why": "Their or-answers agree; their both-answers differ."}, {"q": "A test catches 9 infected trees in 10. What else fixes the chance that a flagged tree is infected?", "a": "the wrong-flag rate and the share infected", "w": ["the wrong-flag rate alone", "the number of trees tested", "nothing else"], "why": "Start-matters: the turned arrow is made of f and the start."}, {"q": "The same test is used in a stand where half the trees are infected. The chance that a flagged tree is infected is then", "a": "18/19", "w": ["18/67", "9/10", "1/2"], "why": "0.45 over 0.45 + 0.025."}, {"q": "A draw gives every part of 4 counties out of 36 the same chance. What is one county’s chance of being in?", "a": "1/9", "w": ["1/36", "1/4", "4/58 905"], "why": "Sees-nothing: one chance for all, and the chances total 4."}, {"q": "The first four names in the alphabet are taken as the sample. Which shuffle shows that this draw sees the members?", "a": "a swap of a name in with a name out", "w": ["a swap of two names that are in", "a swap of two names that are out", "no shuffle shows it"], "why": "The swapped part has chance 0, not 1."}, {"q": "HTTHT and TTHHT, at the guess p = 0.3. How do their chances compare?", "a": "they are equal", "w": ["the first is greater", "the second is greater", "it depends on the coin"], "why": "Count-carries: both have the count (5, 2)."}, {"q": "A coin shows 3 heads in 5, then 1 head in 15. What is the best guess from both records?", "a": "0.2", "w": ["0.33", "0.6", "0.07"], "why": "Counts add: (5, 3) + (15, 1) = (20, 4)."}, {"q": "Two records have shares 0.6 and 0.2. What more is needed for the pooled best guess?", "a": "how many tosses each had", "w": ["the order of the tosses", "which record came first", "nothing more"], "why": "The pooled guess does not pass through the shares."}, {"q": "Sixty plots in three twenties give about 5.8 × 10²⁶ splits. How is the label shuffle still done?", "a": "on a fair sample of the splits", "w": ["by listing every split", "on the first ten thousand listed", "it cannot be done"], "why": "A fair sample has the population’s own share on average."}, {"q": "Its accepted name: a summary through which the likelihood passes at every guess.", "a": "a sufficient statistic", "w": ["an unbiased estimator", "a posterior", "a simple random sample"], "why": "For tosses of one coin, the count (n, k) is one."}];
